code='''from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = collections.Counter(x for row in grid for x in row).most_common(1)[0][0]
    seen=set()
    q=deque()
    for r in range(h):
        for c in (0,w-1):
            if grid[r][c]==bg and (r,c) not in seen:
                seen.add((r,c)); q.append((r,c))
    for c in range(w):
        for r in (0,h-1):
            if grid[r][c]==bg and (r,c) not in seen:
                seen.add((r,c)); q.append((r,c))
    while q:
        r,c=q.popleft()
        for nr,nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
            if 0<=nr<h and 0<=nc<w and grid[nr][nc]==bg and (nr,nc) not in seen:
                seen.add((nr,nc)); q.append((nr,nc))
    out=[row[:] for row in grid]
    enclosed=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==bg and (r,c) not in seen]
    # Small 2-by-2 cavities are marked 2; other enclosed cavities are marked 7.
    # Group cavities so the special color depends on the cavity dimensions.
    unseen=set(enclosed)
    while unseen:
        start=unseen.pop(); comp={start}; qq=[start]
        while qq:
            r,c=qq.pop()
            for p in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if p in unseen:
                    unseen.remove(p); comp.add(p); qq.append(p)
        rows=[p[0] for p in comp]; cols=[p[1] for p in comp]
        color=2 if len(comp)==4 and max(rows)-min(rows)==1 and max(cols)-min(cols)==1 else 7
        for r,c in comp: out[r][c]=color
    return out
'''
